-- Public readers see only intentional publications. Drafts/history stay private.
create schema if not exists brainilab_editor;
revoke all on schema brainilab_editor from public, anon;
grant usage on schema brainilab_editor to authenticated;

create table brainilab_editor.articles (
 slug text primary key check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and length(slug) <= 120),
 document jsonb not null check (jsonb_typeof(document)='object' and octet_length(document::text)<200000),
 revision integer not null default 1,
 updated_at timestamptz not null default now(),
 updated_by uuid references auth.users(id) on delete set null
);
create table brainilab_editor.revisions (
 slug text not null references brainilab_editor.articles(slug),
 revision integer not null,
 document jsonb not null,
 action text not null,
 created_at timestamptz not null default now(),
 created_by uuid references auth.users(id) on delete set null,
 primary key (slug,revision)
);
create table public.learn_publications (
 slug text primary key references brainilab_editor.articles(slug),
 document jsonb not null,
 revision integer not null,
 published_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
alter table brainilab_editor.articles enable row level security;
alter table brainilab_editor.revisions enable row level security;
alter table public.learn_publications enable row level security;
revoke all on brainilab_editor.articles,brainilab_editor.revisions from public,anon,authenticated;
revoke all on public.learn_publications from public,anon,authenticated;
grant select on public.learn_publications to anon,authenticated;
create policy "Published articles are public" on public.learn_publications for select to anon,authenticated using (true);

-- Definer helpers are in a non-exposed schema. Every entry checks active role/MFA.
-- Direct writes are revoked so revision checks and validation cannot be bypassed.
create function brainilab_editor.list_articles() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform public.require_brainilab_admin(array['owner','editor']);
 return coalesce((select jsonb_agg(jsonb_build_object('slug',a.slug,'document',a.document,'revision',a.revision,'updated_at',a.updated_at,'published_revision',p.revision,'published_at',p.published_at) order by a.updated_at desc) from brainilab_editor.articles a left join public.learn_publications p using(slug)),'[]'::jsonb);
end $$;

create function brainilab_editor.save_article(p_slug text,p_document jsonb,p_revision integer,p_action text) returns jsonb language plpgsql security definer set search_path='' as $$
declare v_uid uuid; v_current integer; v_revision integer; v_document jsonb; v_section jsonb; v_link jsonb; v_first timestamptz; v_ids text[]:=array[]::text[];
begin
 v_uid:=public.require_brainilab_admin(array['owner','editor']);
 if p_slug is null or p_slug !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or length(p_slug)>120 then raise exception 'Use a short URL with lowercase letters, numbers and hyphens.'; end if;
 if p_action not in ('draft','publish','unpublish') or p_action is null then raise exception 'Invalid action'; end if;
 if p_document is null or jsonb_typeof(p_document)<>'object' or octet_length(p_document::text)>190000 then raise exception 'Article is too large or invalid'; end if;
 if length(trim(coalesce(p_document->>'title','')))=0 or length(p_document->>'title')>180 then raise exception 'Add a title (maximum 180 characters).'; end if;
 if length(coalesce(p_document->>'description',''))>400 or length(coalesce(p_document->>'topic',''))>60 then raise exception 'Description or topic is too long.'; end if;
 if coalesce(jsonb_typeof(p_document->'sections'),'null')<>'array' or jsonb_array_length(p_document->'sections')>40 then raise exception 'Use up to 40 sections.'; end if;
 for v_section in select value from jsonb_array_elements(p_document->'sections') loop
  if coalesce(v_section->>'id','') !~ '^[a-z0-9]+(-[a-z0-9]+)*$' or v_section->>'id'=any(v_ids) or v_section->>'id'='sources' then raise exception 'Section IDs must be unique.'; end if;
  v_ids:=array_append(v_ids,v_section->>'id');
 end loop;
 if p_action='publish' then
  if trim(coalesce(p_document->>'description',''))='' or trim(coalesce(p_document->>'topic',''))='' or jsonb_array_length(p_document->'sections')=0 or trim(coalesce(p_document->>'practice',''))='' then raise exception 'Add a description, topic, article sections and game invitation before publishing.'; end if;
  if trim(coalesce(p_document#>>'{cover,alt}',''))='' or trim(coalesce(p_document#>>'{cover,credit}',''))='' or coalesce(p_document#>>'{cover,src}','') !~ '^(/assets/images/learn/[a-z0-9-]+\.webp|https://wvgcdlxebbybthyuajgb\.supabase\.co/storage/v1/object/public/learn-covers/[a-zA-Z0-9_./-]+\.(webp|png|jpg|jpeg))$' then raise exception 'Choose an article cover and add its description and credit.'; end if;
  for v_link in select p_document->'game' union all select p_document->'hub' loop
   if trim(coalesce(v_link->>'name',''))='' or coalesce(v_link->>'url','') !~ '^/[a-z0-9][a-z0-9/-]*/$' then raise exception 'Choose valid game and topic links.'; end if;
  end loop;
  if coalesce(jsonb_typeof(p_document->'sources'),'null')<>'array' or jsonb_array_length(p_document->'sources')=0 then raise exception 'Add at least one source.'; end if;
  for v_link in select value from jsonb_array_elements(p_document->'sources') loop
   if trim(coalesce(v_link->>'name',''))='' or coalesce(v_link->>'url','') !~ '^https://' then raise exception 'Each source needs a name and HTTPS link.'; end if;
  end loop;
 end if;
 -- A transaction-level lock also covers simultaneous first saves.
 perform pg_advisory_xact_lock(hashtextextended('learn:'||p_slug,0));
 select revision into v_current from brainilab_editor.articles where slug=p_slug for update;
 if coalesce(v_current,0)<>coalesce(p_revision,-1) then raise exception 'This article changed in another session. Reload the saved version before saving again.'; end if;
 v_revision:=coalesce(v_current,0)+1;
 select published_at into v_first from public.learn_publications where slug=p_slug;
 v_first:=coalesce(v_first,now());
 v_document:=p_document||jsonb_build_object('slug',p_slug,'status',case when p_action='publish' then 'published' else 'draft' end);
 if p_action='publish' then v_document:=v_document||jsonb_build_object('publishedAt',v_first,'updatedAt',now()); end if;
 insert into brainilab_editor.articles(slug,document,revision,updated_by) values(p_slug,v_document,v_revision,v_uid)
 on conflict(slug) do update set document=excluded.document,revision=excluded.revision,updated_at=now(),updated_by=v_uid;
 insert into brainilab_editor.revisions(slug,revision,document,action,created_by) values(p_slug,v_revision,v_document,p_action,v_uid);
 if p_action='publish' then
  insert into public.learn_publications(slug,document,revision,published_at) values(p_slug,v_document,v_revision,v_first)
  on conflict(slug) do update set document=excluded.document,revision=excluded.revision,updated_at=now();
 elsif p_action='unpublish' then delete from public.learn_publications where slug=p_slug;
 end if;
 perform public.log_brainilab_admin_action('article_'||p_action,'learn_article',p_slug,jsonb_build_object('revision',v_revision));
 return jsonb_build_object('slug',p_slug,'revision',v_revision,'document',v_document,'action',p_action);
end $$;

create function brainilab_editor.article_history(p_slug text) returns jsonb language plpgsql security definer set search_path='' as $$
begin
 perform public.require_brainilab_admin(array['owner','editor']);
 return coalesce((select jsonb_agg(r order by r.revision desc) from (select revision,document,action,created_at from brainilab_editor.revisions where slug=p_slug order by revision desc limit 30) r),'[]'::jsonb);
end $$;
revoke all on function brainilab_editor.list_articles(),brainilab_editor.save_article(text,jsonb,integer,text),brainilab_editor.article_history(text) from public,anon;
grant execute on function brainilab_editor.list_articles(),brainilab_editor.save_article(text,jsonb,integer,text),brainilab_editor.article_history(text) to authenticated;
create function public.admin_list_learn_articles() returns jsonb language sql security invoker set search_path='' as $$ select brainilab_editor.list_articles(); $$;
create function public.admin_save_learn_article(p_slug text,p_document jsonb,p_revision integer,p_action text default 'draft') returns jsonb language sql security invoker set search_path='' as $$ select brainilab_editor.save_article(p_slug,p_document,p_revision,p_action); $$;
create function public.admin_learn_article_history(p_slug text) returns jsonb language sql security invoker set search_path='' as $$ select brainilab_editor.article_history(p_slug); $$;
revoke all on function public.admin_list_learn_articles(),public.admin_save_learn_article(text,jsonb,integer,text),public.admin_learn_article_history(text) from public,anon;
grant execute on function public.admin_list_learn_articles(),public.admin_save_learn_article(text,jsonb,integer,text),public.admin_learn_article_history(text) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values('learn-covers','learn-covers',true,3145728,array['image/webp','image/png','image/jpeg']) on conflict(id) do nothing;
create policy "Editors add Learn covers" on storage.objects for insert to authenticated with check (bucket_id='learn-covers' and (select public.require_brainilab_admin(array['owner','editor'])) is not null);
create policy "Editors read Learn cover metadata" on storage.objects for select to authenticated using (bucket_id='learn-covers' and (select public.require_brainilab_admin(array['owner','editor'])) is not null);

-- Seed existing reviewed publications once. Future changes are managed in Admin.
insert into brainilab_editor.articles(slug,document) values('connections-puzzles-find-the-hidden-link','{"slug": "connections-puzzles-find-the-hidden-link", "status": "published", "topic": "Words & puzzles", "title": "Connections puzzles: test the link against every clue", "description": "The first association is only a candidate. A good connection has to explain the whole set.", "game": {"name": "Connections", "url": "/games/connections/"}, "hub": {"name": "All games", "url": "/games/"}, "sections": [{"id": "first-association", "title": "Your first thought can be useful—and incomplete", "html": "<p>Read these four words: bark, trunk, leaf, root. ‘Tree’ is an immediate connection. But bark can also be a dog’s sound, a trunk can hold luggage, and a root can belong to an equation.</p><p>A connection puzzle makes you choose which meaning matters in this particular set. Start with your first association, then test it. A strong answer should explain all the clues through the same idea.</p>"}, {"id": "specific-test", "title": "Make the category specific enough to check", "html": "<p>‘Things you can find outside’ is broad enough to accept almost anything. ‘Parts of a tree’ makes a sharper claim. You can examine each word and ask whether it belongs.</p><p>In BrainiLab Connections, you choose the relationship from the available answers. Do not assume it uses the rules of another game with a similar name. Read the prompt and choices before deciding what counts as a successful answer.</p><p>Try mentally completing the sentence ‘Each clue is a…’ or ‘Each word can follow…’. If you have to change the sentence for one clue, your connection may be too loose.</p>"}, {"id": "odd-clue", "title": "Pay attention to the awkward clue", "html": "<p>Suppose three clues fit your idea immediately and one refuses. Instead of treating the awkward word as an exception, make it the centre of your next attempt. List another meaning for that word and see whether it changes your reading of the other three.</p><p>This is a practical pause, not a demand to invent dozens of possibilities. Test a small number of precise alternatives. The goal is to find a common explanation, not the most imaginative story.</p><details class=\"practice-answer\"><summary>What links keys, space and return in a familiar computer context?</summary><p>A keyboard. “Space” and “return” can name keys, while “keys” gives the broader context. The context matters: those words have other meanings too.</p></details>"}, {"id": "after-answer", "title": "After the reveal, explain the weakest fit", "html": "<p>When the answer appears, choose the clue you understood least well and explain how it fits. If it uses an unfamiliar meaning, look that meaning up rather than simply memorising the answer label.</p><p>For your next round, remember the move that helped: checking a second meaning, tightening the category or testing the odd clue. That is something you can reuse even when none of the words repeat.</p>"}], "sources": [{"name": "BrainiLab — Connections rules and play", "url": "/games/connections/"}], "related": ["number-sequences-look-at-the-gaps", "remember-quiz-answers-tomorrow"], "practice": "Try Connections. Before choosing, check that the proposed relationship explains every clue in the round.", "cover": {"src": "/assets/images/learn/connections-puzzles-find-the-hidden-link.webp", "alt": "Red objects grouped together on a table", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 5, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='connections-puzzles-find-the-hidden-link' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='connections-puzzles-find-the-hidden-link' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('counting-seconds-after-lightning','{"slug": "counting-seconds-after-lightning", "status": "published", "topic": "Science & nature", "title": "What the gap between lightning and thunder tells you", "description": "A flash, a pause, a rumble: use the delay to understand how sound travels.", "game": {"name": "Science Quiz", "url": "/science/science-quiz/"}, "hub": {"name": "Science", "url": "/science/"}, "sections": [{"id": "one-event", "title": "One event arrives in two ways", "html": "<p>You see the flash through the window. A few seconds later, the room fills with a rumble. The light and sound belong to the same lightning event, but they do not reach you at the same speed.</p><p>Light arrives so quickly over these distances that its travel time is negligible for this estimate. Sound takes roughly three seconds to travel a kilometre, or five seconds to travel a mile. The delay gives a rough distance to the lightning, not a precise location for the whole storm.</p>"}, {"id": "work-it-out", "title": "Work through a nine-second gap", "html": "<p>If you count nine seconds, divide by three for an estimate in kilometres: about three kilometres. For miles, divide the same nine seconds by five: about 1.8 miles. Those answers describe roughly the same distance in different units.</p><p>Do not multiply just because the numbers feel familiar. Write the relationship first: more seconds should mean farther away. Then label the result. ‘Three’ on its own could be a time, a distance or the wrong unit.</p>"}, {"id": "safe-observation", "title": "An estimate is not a safety test", "html": "<p>If you hear thunder, lightning is close enough to be a danger. Go indoors; do not stand outside to improve the measurement. The US National Weather Service advises staying in safe shelter for at least 30 minutes after the last thunder. Use a worked example like the one here to practise the arithmetic.</p><details class=\"practice-answer\"><summary>In a worked example, the delay is 15 seconds. About how far away is the lightning in kilometres?</summary><p>About five kilometres: 15 ÷ 3. This is a rough estimate and does not establish that an outdoor location is safe.</p></details>"}, {"id": "one-more-check", "title": "Check the direction of your answer", "html": "<p>Imagine another flash with half the delay. Without calculating, predict whether it was nearer or farther away. Then do the calculation. Building this quick reasonableness check into a quiz helps catch errors that a perfectly tidy calculation can hide.</p>"}], "sources": [{"name": "NOAA — Determining distance to a thunderstorm", "url": "https://www.noaa.gov/jetstream/lightning/sound-of-thunder/learning-lesson-determining-distance-to-thunderstorm"}, {"name": "National Weather Service — Lightning safety", "url": "https://www.weather.gov/safety/lightning-tips"}], "related": ["what-really-causes-seasons", "mental-percentages-without-a-calculator"], "practice": "Try Science Quiz for more everyday science. This reading exercise does not require observing a storm outdoors.", "cover": {"src": "/assets/images/learn/counting-seconds-after-lightning.webp", "alt": "Distant lightning seen through a rain-covered window", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 12, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='counting-seconds-after-lightning' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='counting-seconds-after-lightning' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('daily-or-anytime','{"slug": "daily-or-anytime", "status": "published", "topic": "Getting started", "title": "Daily or Anytime? Find a game that suits your break", "description": "One shared challenge or a topic of your choice: here’s where to start.", "game": {"name": "Today’s Daily games", "url": "/daily-quiz/"}, "hub": {"name": "All games", "url": "/games/"}, "sections": [{"id": "choose", "title": "Start with the kind of session you want", "html": "<p>Some days you want one clear challenge. On others, you want to practise a topic until it feels more familiar. BrainiLab has two ways to choose: Daily challenges provide a shared set for the day, while Anytime games let you choose what to play whenever you visit.</p><p>You can start without registering. If you later want to keep progress across devices, sign in through My Stats. Guest play can appear in rankings under a generated alias, so playing without an account does not necessarily mean your result is excluded from a public leaderboard.</p>"}, {"id": "daily", "title": "Choose Daily for a clear next step", "html": "<p>Open the Daily page to see the current challenges and which ones you have completed. The Daily Brain Score combines four scored games, each contributing up to 2,500 points, for a maximum of 10,000. The page is the place to check the actual games in today’s set; do not assume every game on the website contributes to that total.</p><p>Brain Mix is a useful place to begin if you like varied questions. Finish a game, read the result and return to the Daily page to choose an unfinished challenge. Different games use different performance measures, so a raw quiz point total and the combined Daily Brain Score are not interchangeable.</p><p>After completing today’s set, you can return for another Daily on a later day or move into practice. A replay or past challenge should not be assumed to count as a new scored Daily: check the mode label before starting.</p>"}, {"id": "anytime", "title": "Choose Anytime when you have a topic in mind", "html": "<p>The games library offers subject quizzes and different mechanics. Try World Flags for visual recognition, World Capitals for place names, or General Knowledge for a mixture. Where a quiz offers difficulty levels, choose the one that gives you a useful amount of challenge rather than treating the hardest label as a requirement.</p><p>If you want a change of pace, try a number or word game. Read its guide first: a worked example can make a new mechanic easier to understand than learning every rule during a timed round. Anytime means you can choose your session; it does not mean every game uses the same rules or the same scoring system.</p>"}, {"id": "result", "title": "Use the result to make one decision", "html": "<p>Before moving on, ask what the result tells you. Was there a fact you did not know, an instruction you misunderstood, or a question you rushed? Pick one thing to revisit. That gives the next session a purpose without turning every game into homework.</p><ul><li><strong>A topic caught your attention:</strong> follow its subject hub and choose a related quiz.</li><li><strong>You confused two answers:</strong> write down the difference you want to check.</li><li><strong>You enjoyed the format:</strong> try another game with a similar pace.</li></ul><p>For example, an uncertain flag answer can lead to our flag practice guide and then another World Flags round. You can also share a completed result using the game’s sharing controls if you want to compare with friends.</p>"}, {"id": "return", "title": "Keep your next visit simple", "html": "<p>Choose one next action: finish another Daily game, practise a topic, or save your progress with an account. You do not need to do all three in one visit. The next time you open BrainiLab, the Daily page gives you a starting point and the games library gives you alternatives.</p><p>BrainiLab+ is optional support for the project. It does not give extra points, attempts or ranking advantages. Read the membership page for current benefits and the advertising status before subscribing; playing and learning do not require Plus.</p>"}], "sources": [{"name": "BrainiLab — Daily games and score", "url": "/daily-quiz/"}, {"name": "BrainiLab — Games library", "url": "/games/"}, {"name": "BrainiLab — Membership details", "url": "/plus/"}], "related": ["how-to-learn-world-flags"], "cover": {"src": "/assets/images/learn/daily-or-anytime.webp", "alt": "Tea, a notebook and wooden puzzle pieces on a morning table", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 13, "practice": "See today’s Daily games and choose one you feel like playing.", "publishedAt": "2026-09-23T15:00:00Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='daily-or-anytime' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='daily-or-anytime' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('how-to-learn-world-flags','{"slug": "how-to-learn-world-flags", "status": "published", "topic": "Geography", "title": "How to learn world flags: look for one useful clue", "description": "A practical way to study flags: describe the pattern, compare confusing pairs and turn quiz mistakes into a small practice list.", "game": {"name": "World Flags Quiz", "url": "/geography/world-flags-quiz/?difficulty=easy&set=1"}, "hub": {"name": "Flags learning hub", "url": "/geography/flags/"}, "sections": [{"id": "start-small", "title": "Start with a small set", "html": "<p>A page full of flags can quickly become a blur of stripes, stars and familiar colours. Give yourself a smaller task: choose five flags, describe each one, then try to name them without looking at the labels. Keep the list short enough that you can explain each design without rushing.</p><p>Before you begin a quiz, decide what you want to practise. You might focus on vertical stripes, flags with a central symbol, or a handful of countries you keep mixing up. A specific question such as ‘Which colour is next to the flagpole?’ gives you something concrete to check when you get an answer wrong.</p>"}, {"id": "describe", "title": "Describe the design before naming the country", "html": "<p>Use the same short checklist each time. First look at the layout: horizontal bands, vertical bands, a cross, or a single background. Next identify the colours in order. Finally look for a symbol and where it sits.</p><ul><li><strong>Layout:</strong> which shapes divide the flag?</li><li><strong>Order:</strong> what comes first, next and last?</li><li><strong>Detail:</strong> is there an emblem, star or other mark?</li></ul><p>Be precise about direction. The hoist is the edge attached to the flagpole. In a standard front-facing illustration with the pole on the left, read vertical bands from left to right. Do not assume a mirrored photograph has the same orientation.</p>"}, {"id": "worked-example", "title": "A worked example: Italy", "html": "<div class=\"flag-example\"><div class=\"italy-flag\" role=\"img\" aria-label=\"Illustration of Italy’s flag: equal vertical bands of green, white and red\"></div><p><strong>Italy:</strong> three equal vertical bands, green, white and red, starting at the hoist. This description is set out in Article 12 of the Italian Constitution, reproduced by the Italian Presidency.</p></div><p>Try saying the distinguishing clue before the country: ‘Vertical stripes, green at the hoist, white in the middle, red at the outer edge.’ That is more useful for checking a mistake than ‘the red and green one’. The illustration is a simplified study aid, not a specification for manufacturing a flag.</p><details class=\"practice-answer\"><summary>Quick check: which colour is at the hoist of Italy’s flag?</summary><p><strong>Green.</strong> The full order is green, white, red. If you answered red, check whether you reversed the direction rather than confusing the country.</p></details>"}, {"id": "compare", "title": "Compare the pair you actually confused", "html": "<p>When two flags look similar to you, place their labelled illustrations side by side. Write down one difference that you can point to: the order of the bands, the presence of an emblem, or the position of a shape. Then cover the names and explain the difference in your own words.</p><p>Avoid relying on a subtle colour shade in a small quiz image. Screens, image files and lighting can change how a colour appears. If the distinction depends on official proportions or a precise shade, consult an authoritative reference rather than inventing a visual rule from two thumbnails.</p>"}, {"id": "review", "title": "Turn a result into your next practice list", "html": "<p>Play a round of World Flags, then use the answer feedback to make a short list. For each uncertain answer, note the country, what you chose and the detail you missed. Include correct guesses too: a correct answer does not always mean you recognised the flag confidently.</p><p>On your next visit, try describing those flags before starting another round. If the same confusion comes up, change your note from a vague label to an observable difference. Keep the note for your next visit. A list of three specific mistakes is easier to use than starting again with a page full of flags.</p><p>Once you are comfortable, try another difficulty or connect your flag practice with the World Capitals quiz. You do not need to memorise every flag before exploring another geography topic.</p>"}], "sources": [{"name": "Italian Presidency — The Italian Tricolour Flag", "url": "https://www.quirinale.it/it/pagine/italian-tricolour-flag"}], "related": ["daily-or-anytime"], "cover": {"src": "/assets/images/learn/how-to-learn-world-flags.webp", "alt": "Table flags of Japan, Italy and Sweden beside a notebook", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 1, "practice": "Try World Flags. For each uncertain answer, look for the stripe, shape or symbol that distinguishes it.", "publishedAt": "2026-09-23T15:00:00Z"}'::jsonb) on conflict do nothing;
