insert into brainilab_editor.articles(slug,document) values('mental-percentages-without-a-calculator','{"slug": "mental-percentages-without-a-calculator", "status": "published", "topic": "Numbers & logic", "title": "Mental percentages: start with 10%, then build", "description": "A few easy pieces can handle awkward-looking percentages. Try 15%, 25% and 12% step by step.", "game": {"name": "Math Rush", "url": "/games/math-rush/"}, "hub": {"name": "All games", "url": "/games/"}, "sections": [{"id": "ten-first", "title": "Find a piece you already know", "html": "<p>‘What is 15% of 80?’ can trigger an unnecessary search for a formula. Start with 10% instead: eight. Half of that is 5%: four. Add the two pieces and you have twelve.</p><p>Percent means per hundred. Finding 10% is dividing by ten, not always removing a zero. Ten percent of 37 is 3.7. Keep the meaning in view when the number stops looking neat.</p>"}, {"id": "useful-pieces", "title": "Choose the easiest pieces for this number", "html": "<ul><li><strong>25%:</strong> one quarter. For 80, divide by four to get 20.</li><li><strong>50%:</strong> one half. For 46, halve it to get 23.</li><li><strong>1%:</strong> divide by 100. For 250, that gives 2.5.</li></ul><p>Now try 12% of 250. Ten percent is 25; two percent is twice 2.5, or 5. Together they make 30. There is no prize for using the longest method. Pick the pieces that make the calculation comfortable.</p>"}, {"id": "of-what", "title": "The important question: percent of what?", "html": "<p>A percentage needs a base. If a quantity of 100 falls by 20%, it becomes 80. Increasing that new quantity by 20% adds 16, taking it to 96—not back to 100. The percentage is the same; the base has changed.</p><p>Write the base next to each step if a question involves successive changes. This simple habit prevents a common mistake even when every individual multiplication is correct.</p><details class=\"practice-answer\"><summary>What is 15% of 60? Work it out before opening.</summary><p>9. Ten percent is 6; five percent is 3; add them. As a check, 15% should be less than one quarter of 60, which is 15.</p></details>"}, {"id": "practice-pair", "title": "Make one example into two", "html": "<p>After solving the example, change just one number. Try 15% of 120, then explain why the answer doubles. If the method still feels uncertain, slow down and name the pieces out loud: ten percent, five percent, total.</p><p>Math Rush uses quick arithmetic rather than a dedicated percentage lesson. It is a place to practise the underlying adding, halving and multiplying after trying these examples without a timer.</p>"}], "sources": [{"name": "OpenStax — Prealgebra: percent concepts", "url": "https://openstax.org/books/prealgebra/pages/6-key-concepts"}], "related": ["number-sequences-look-at-the-gaps", "counting-seconds-after-lightning"], "practice": "Practise the arithmetic in Math Rush. Build accuracy first; the percentage examples above can be worked through at your own pace.", "cover": {"src": "/assets/images/learn/mental-percentages-without-a-calculator.webp", "alt": "Oranges and a balance scale at a market", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 2, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='mental-percentages-without-a-calculator' on conflict do nothing;
