insert into brainilab_editor.articles(slug,document) values('number-sequences-look-at-the-gaps','{"slug": "number-sequences-look-at-the-gaps", "status": "published", "topic": "Numbers & logic", "title": "Stuck on a number sequence? Look at the gaps", "description": "Try differences, multipliers and alternating patterns before reaching for a complicated rule.", "game": {"name": "Sequence", "url": "/games/sequence/"}, "hub": {"name": "All games", "url": "/games/"}, "sections": [{"id": "between-numbers", "title": "Look between the numbers", "html": "<p>Consider 4, 7, 10, 13. Instead of staring at the values, ask what happens from one to the next. Each step adds three, so 16 is a natural continuation.</p><p>Write the differences underneath: +3, +3, +3. You have turned four numbers into a simpler pattern. The same move can reveal a rule that was difficult to see in the original line.</p>"}, {"id": "growing-gaps", "title": "What if the gaps are changing?", "html": "<p>Try 2, 5, 10, 17. The gaps are +3, +5, +7. Continuing with the next odd gap, +9, gives 26. Check your rule against every displayed step, not just the last two numbers.</p><p>Now compare 3, 6, 12, 24. The gaps are growing, but repeated doubling gives a much simpler explanation. Differences are a first tool, not the only one.</p>"}, {"id": "two-lines", "title": "Sometimes there are two interleaved lines", "html": "<p>For 2, 10, 4, 20, 6, 30, separate alternate positions. The first, third and fifth terms are 2, 4, 6; the second, fourth and sixth are 10, 20, 30. A plausible next term is 8.</p><p>On paper, use two colours or two rows. That is more reliable than trying to keep both patterns floating in your head. When a sequence swings between small and large values, this is worth a quick check.</p><details class=\"practice-answer\"><summary>Continue 5, 9, 15, 23 using gaps that increase by two.</summary><p>33. The gaps are 4, 6 and 8; the next is 10, so 23 + 10 = 33.</p></details>"}, {"id": "not-proof", "title": "A plausible pattern is not a mathematical proof", "html": "<p>A finite list can fit many rules. Without a stated rule, ‘the next number’ is not always uniquely determined. Puzzle questions generally intend a simple pattern supported by all the clues and answer choices.</p><p>Use a short checklist: constant difference, repeated multiplier, changing differences, alternating lines. Then read the available answers. If your rule needs a fresh exception at every step, try a simpler explanation before committing.</p><p>When you get one wrong, record the type of pattern you missed. ‘I forgot to test alternate terms’ is a more useful note than ‘I am bad at sequences’.</p>"}], "sources": [{"name": "University of Cambridge NRICH — Patterns, sequences and structure", "url": "https://nrich.maths.org/tags/patterns-sequences-and-structure"}, {"name": "BrainiLab — Sequence rules and play", "url": "/games/sequence/"}], "related": ["mental-percentages-without-a-calculator", "connections-puzzles-find-the-hidden-link"], "practice": "Open Sequence and try the checklist on a round. Use the explanation to check whether your rule fits all the terms.", "cover": {"src": "/assets/images/learn/number-sequences-look-at-the-gaps.webp", "alt": "Pebbles arranged in growing groups", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 9, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='number-sequences-look-at-the-gaps' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='number-sequences-look-at-the-gaps' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('remember-quiz-answers-tomorrow','{"slug": "remember-quiz-answers-tomorrow", "status": "published", "topic": "Learning", "title": "How to remember a quiz answer after the quiz is over", "description": "Pick one surprising answer, close the explanation and see whether you can bring it back yourself.", "game": {"name": "General Knowledge Quiz", "url": "/general-knowledge/general-knowledge-quiz/"}, "hub": {"name": "General knowledge", "url": "/general-knowledge/"}, "sections": [{"id": "familiar", "title": "“I knew that” is not quite the same as remembering", "html": "<p>You read an answer explanation and it seems obvious. A day later, the same question leaves you staring at the options. The explanation may have felt familiar without being easy to retrieve on your own.</p><p>Research on retrieval practice distinguishes reading information again from trying to recall it. In the studies discussed by Roediger and Karpicke, testing could support later retention even when repeated study felt more fluent in the moment. That does not make every quiz a complete learning programme; what you do with the answer still matters.</p>"}, {"id": "one-answer", "title": "Choose one answer worth keeping", "html": "<p>After a round, choose a fact you actually care about. Write a question on one side of a card and the answer, with a short explanation, on the other. ‘How many hearts does an octopus have, and what do they do?’ is more useful than a card containing only the word ‘octopus’.</p><p>Close the feedback before answering your own question. Say what you remember, then check. Correct a mistake immediately in your note so that you do not keep practising a confident error.</p>"}, {"id": "later", "title": "Try again after a gap", "html": "<p>Put the card aside. On a later day, try it before turning it over. If you remember the idea easily, make the question slightly different: explain why, give an example or contrast it with a common mistake. If you cannot recall it, shorten the question and check the explanation again.</p><p>This is a small routine to try, not a universal schedule. The useful difficulty depends on what you already know and how long you want to retain it. One honest attempt is better than pretending that recognising the printed answer counts as recall.</p><details class=\"practice-answer\"><summary>Which checks recall more directly: rereading an answer or covering it and explaining it yourself?</summary><p>Covering it and explaining it yourself. Afterwards, check the original so that mistakes do not go uncorrected.</p></details>"}, {"id": "keep-it-small", "title": "Keep the pile small enough to use", "html": "<p>You do not need a card for every mistake. Start with three questions that interested you. Remove or rewrite cards that are vague, and include an explanation when a bare fact keeps slipping away.</p><p>After your next quiz, compare one confident answer with one guess. Both may have earned the same points, but only one tells you that the idea was readily available. Let that distinction guide what you practise.</p>"}], "sources": [{"name": "Roediger & Karpicke — The power of testing memory (research review)", "url": "https://learninglab.psych.purdue.edu/downloads/2006/2006_Roediger_Karpicke_Review.pdf"}], "related": ["why-octopuses-have-three-hearts", "how-to-learn-world-flags"], "practice": "Play a General Knowledge round and choose just one answer to explain from memory after reading the feedback.", "cover": {"src": "/assets/images/learn/remember-quiz-answers-tomorrow.webp", "alt": "Index cards, a notebook and a pencil ready for practice", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 7, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='remember-quiz-answers-tomorrow' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='remember-quiz-answers-tomorrow' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('what-really-causes-seasons','{"slug": "what-really-causes-seasons", "status": "published", "topic": "Science & nature", "title": "Summer isn’t caused by being closer to the Sun", "description": "The useful clue is Earth’s tilt—and the opposite seasons on either side of the equator.", "game": {"name": "Science Quiz", "url": "/science/science-quiz/"}, "hub": {"name": "Science", "url": "/science/"}, "sections": [{"id": "tempting-answer", "title": "The tempting answer does not fit", "html": "<p>Stand nearer a heater and you feel warmer. It is an appealing explanation for summer: perhaps Earth has simply moved closer to the Sun. But it cannot explain why June is summer in the Northern Hemisphere and winter in the Southern Hemisphere.</p><p>Earth’s tilted axis is the main cause of the seasons. As Earth orbits the Sun, a hemisphere tilted towards it receives more direct sunlight and longer days. Six months later, the other hemisphere has that advantage.</p>"}, {"id": "light-and-time", "title": "Both the angle and the hours matter", "html": "<p>Think about sunlight striking a surface head-on compared with arriving at a low angle. At a low angle, the light is spread across more surface. Add fewer hours of daylight and the heating changes again.</p><p>NASA points out a useful check on the distance explanation: Earth is closest to the Sun in January, during Northern Hemisphere winter. The orbit is not a perfect circle, but its changing distance is not what produces Earth’s familiar seasonal pattern.</p>"}, {"id": "test-explanation", "title": "Use the opposite-season test", "html": "<p>Write down the proposed explanation ‘The whole planet is warmer because it is closer.’ Now ask what that would predict for both hemispheres at the same time. Compare it with the opposite-season pattern. A good explanation must account for both observations.</p><p>This is a useful quiz habit: rather than asking whether an answer sounds familiar, ask what else would have to be true if it were correct. One counterexample can be more helpful than repeating a definition.</p><details class=\"practice-answer\"><summary>When the Northern Hemisphere tilts towards the Sun, which hemisphere receives more direct sunlight?</summary><p>The Northern Hemisphere. The Southern Hemisphere is tilted away.</p></details>"}, {"id": "next-walk", "title": "Notice one local change", "html": "<p>Pick a familiar afternoon walk and notice where the shadows fall. Return at roughly the same clock time a few weeks later and compare, allowing for any clock change. You are collecting a small observation, not measuring the entire climate. Weather on a single day can be unusual; a seasonal pattern is broader than that.</p>"}], "sources": [{"name": "NASA Space Place — What causes the seasons?", "url": "https://spaceplace.nasa.gov/seasons/en/"}], "related": ["why-the-moon-changes-shape", "counting-seconds-after-lightning"], "practice": "Play Science Quiz and look for the explanation behind each answer, rather than trying to memorise a list of disconnected facts.", "cover": {"src": "/assets/images/learn/what-really-causes-seasons.webp", "alt": "Sunlight through autumn leaves on a woodland path", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 8, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='what-really-causes-seasons' on conflict do nothing;
