insert into brainilab_editor.articles(slug,document) values('which-century-is-that-year','{"slug": "which-century-is-that-year", "status": "published", "topic": "History", "title": "Is 1900 in the 19th or 20th century?", "description": "Century names are a counting problem. The boundary years are where the confusion starts.", "game": {"name": "History Quiz", "url": "/history/history-quiz/"}, "hub": {"name": "History", "url": "/history/"}, "sections": [{"id": "boundary", "title": "1900 is the last year of the 19th century", "html": "<p>The first two digits look persuasive. A year beginning ‘19’ must belong to the 20th century, surely? Usually—but the round number at the boundary needs special care.</p><p>In the conventional AD/CE calendar, the first century covers years 1 through 100. The second covers 101 through 200. Continue that count and the 19th century covers 1801–1900; the 20th covers 1901–2000. The US Naval Observatory uses this convention when explaining why the 21st century began in 2001.</p>"}, {"id": "shelf", "title": "Picture shelves that hold 100 years", "html": "<p>Imagine placing year cards on shelves. Shelf one takes cards 1 to 100. Card 101 must go on shelf two. A full shelf ends with the hundredth card, rather than beginning with it.</p><p>This picture is useful because you can rebuild the rule instead of memorising another exception. It also shows why ‘the 1900s’ and ‘the 20th century’ are not identical date ranges. The former commonly describes 1900–1999; the latter uses the numbered-century convention.</p>"}, {"id": "shortcut", "title": "A shortcut for positive CE years", "html": "<p>For a year that does not end in 00, take the hundreds part and add one: 1789 belongs to the 18th century. If the year ends in 00, do not add one: 1800 is still in the 18th.</p><p>In formula form, subtract one from the year, divide by 100, discard the remainder and add one. For 2000, that is 1999 ÷ 100 → 19, then +1 → 20. This shortcut is for positive CE years; do not casually apply it to a BCE date.</p><details class=\"practice-answer\"><summary>Which centuries contain 1600, 1601 and 1999?</summary><p>1600 is in the 16th century; 1601 is in the 17th; 1999 is in the 20th.</p></details>"}, {"id": "reading-dates", "title": "Read the question’s wording", "html": "<p>Underline ‘century’, ‘decade’ or ‘year’ before calculating. A history question may be testing a period name rather than a date conversion. If the answer seems one century out, check the boundary convention before deciding that you have forgotten the historical event.</p>"}], "sources": [{"name": "US Naval Observatory — The 21st century and 3rd millennium", "url": "https://aa.usno.navy.mil/faq/millennium"}], "related": ["how-to-read-roman-numerals", "remember-quiz-answers-tomorrow"], "practice": "Try History Quiz and practise separating the historical fact from the date or century the question asks for.", "cover": {"src": "/assets/images/learn/which-century-is-that-year.webp", "alt": "An open history book and magnifying glass in a library", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 4, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='which-century-is-that-year' on conflict do nothing;
insert into public.learn_publications(slug,document,revision,published_at) select slug,document,revision,(document->>'publishedAt')::timestamptz from brainilab_editor.articles where slug='which-century-is-that-year' on conflict do nothing;
insert into brainilab_editor.articles(slug,document) values('why-greenland-looks-so-big','{"slug": "why-greenland-looks-so-big", "status": "published", "topic": "Geography", "title": "Why does Greenland look so big on a map?", "description": "The map on your wall makes a trade-off. Here’s how to spot it before comparing countries.", "game": {"name": "World Capitals Quiz", "url": "/geography/world-capitals-quiz/"}, "hub": {"name": "Geography", "url": "/geography/"}, "sections": [{"id": "the-map-trick", "title": "The map is stretching something", "html": "<p>Put your finger on Greenland on a familiar rectangular world map. Now look towards the equator. The sizes can feel obvious: surely a bigger patch of paper means a bigger place? That is the trap.</p><p>A globe can represent Earth’s curved surface. A flat map has to distort it. On a Mercator map, the stretching becomes greater towards the poles, so Greenland looks unusually large. The projection is useful for some tasks, but comparing the area of countries is not one of its strengths.</p><p>The US Geological Survey makes a helpful point: there is no single best projection. The useful question is what the map needs to preserve.</p>"}, {"id": "choose-the-tool", "title": "Choose the map for the question", "html": "<p>For area comparisons, try a globe or an equal-area map. Equal-area projections preserve relative areas, while allowing shapes to change. If coastlines look unfamiliar, that does not automatically mean the map is inaccurate.</p><p>Think of two different questions: ‘How much space does this country occupy?’ and ‘What does this local coastline look like?’ They ask different things of the map. Before answering a geography question, check whether the image is evidence for the thing you are comparing.</p>"}, {"id": "try-a-comparison", "title": "Try a two-map comparison", "html": "<p>Choose one place near the equator and one farther north. Find both on a globe, then on a rectangular world map. Ignore the labels for a moment and describe what changed. Did the northern place spread sideways? Did both places keep the same proportions?</p><p>Write one sentence beginning ‘This map is useful for…’ rather than declaring one map good and the other bad. That habit also helps with charts: what a picture makes easy to see matters.</p><details class=\"practice-answer\"><summary>Would an equal-area map have to preserve every country’s shape?</summary><p>No. Preserving relative area and preserving local shape are different properties. A flat world map cannot preserve everything at once.</p></details>"}], "sources": [{"name": "US Geological Survey — Map projections", "url": "https://www.usgs.gov/publications/map-projections"}], "related": ["why-time-zones-get-messy", "how-to-learn-world-flags"], "practice": "Try the World Capitals quiz, then find one unfamiliar country on a globe. The quiz is about places, rather than map projections.", "cover": {"src": "/assets/images/learn/why-greenland-looks-so-big.webp", "alt": "A globe, folded map and compass on a desk", "credit": "AI-generated cover illustration created for BrainiLab."}, "order": 6, "publishedAt": "2026-09-23T19:51:37Z"}'::jsonb) on conflict do nothing;
insert into brainilab_editor.revisions(slug,revision,document,action) select slug,revision,document,'seed' from brainilab_editor.articles where slug='why-greenland-looks-so-big' on conflict do nothing;
